exercise.solution:
struct Book {
    title: String,
    pages: u32,
}

fn make_book(title: &str, pages: u32) -> Book {
    Book {
        title: String::from(title),
        pages: pages,
    }
}

fn main() {
    let book = make_book("Dune", 412);
    println!("{} has {} pages", book.title, book.pages);
}
